#!/usr/bin/env python3
"""Copy the already qualified upstream compact guard verbatim; never reimplement it."""
import argparse
import json
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / 'header-qualification'))
import prepare

def generated():
    manifest, _, source = prepare.checked_sources()
    bodies = '\n\n'.join(prepare.extract.function(source, name) for name in ('checked_target', 'bits_to_target'))
    text = '''// SPDX-License-Identifier: MIT OR Apache-2.0
// Generated by generate_compact.py from the hash-pinned corrected Citrea verifier.
// Only imports, error-type plumbing and the mainnet-limit wrapper are local.
use crypto_bigint::{Encoding, U256};
#[derive(Debug)]
pub enum ValidationError { InvalidBlockBits }
pub fn mainnet_target(bits: u32) -> Result<[u8; 32], ValidationError> {
    checked_target(bits, U256::from_be_hex("00000000ffffffffffffffffffffffffffffffffffffffffffffffffffffffff"))
}
''' + bodies + '\n'
    provenance = dict(upstream_commit='2ed54463bb7c4c3f1ff29dcd66d4b28c26fb63c8',
        corrected_verifier_sha256=manifest['patched_sha256'],
        copied_functions=['checked_target', 'bits_to_target'],
        copied_bodies_sha256=prepare.sha(bodies.encode()), generated_sha256=prepare.sha(text.encode()),
        source_sha256=manifest['source_sha256'])
    return text, json.dumps(provenance, indent=2) + '\n'

def main():
    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, content in zip((HERE/'src/compact.rs', HERE/'compact-source.json'), generated()):
        if args.check:
            if path.read_text() != content: raise ValueError('Generated source differs: ' + str(path))
        else: path.write_text(content)
    print('Pinned compact guard matches')

if __name__ == '__main__': main()
